insert into public.content_blocks (key, value, schema_version) values
  ('PERSONALITY_BY_MONTH_GOD', $json${"비견":"사회에서는 누구에게 기대기보다 스스로 해내려는 모습이 두드러져요. 옛 책은 비견을 형제에 비유하는데, 그만큼 주변 사람을 윗사람이나 아랫사람보다 동등한 동료로 대하는 편이에요. 내 몫과 원칙을 분명히 해서 믿음직하다는 말을 듣지만, 도움을 청하는 데는 서툴 수 있어요. 혼자 감당하기 벅찰 때 먼저 손을 내밀어보면, 기꺼이 도와주는 사람이 생각보다 많다는 걸 알게 돼요.","겁재":"사회에서는 승부욕과 추진력이 먼저 보이는 편이에요. 경쟁이 있는 환경에서 오히려 힘이 나고, 목표가 생기면 빠르게 움직여 분위기를 주도해요. 옛 책은 겁재를 두고 씀씀이와 사람 관계를 살피라고 했는데, 의욕이 앞설 때 지출이 커지거나 사람을 쉽게 믿기 쉬워서예요. 중요한 결정은 하루 묵혀 다시 보고, 혼자 다 떠안으려는 마음을 조금 내려놓으면 추진력이 온전히 장점으로 남아요.","식신":"사회에서는 여유 있고 편안한 사람으로 보이기 쉬워요. 옛 책은 식신을 먹을 복이 넉넉하고 마음이 너그러운 기운으로 풀었는데, 그만큼 서두르지 않고 제 속도로 실력을 쌓는 편이에요. 좋아하는 일을 꾸준히 하다 보면 자연스럽게 결과가 따라오고, 주변 분위기를 부드럽게 만드는 힘이 있어요. 편안함에 머물러 새로운 시도를 미루기 쉬우니, 가끔은 일부러 낯선 일에 도전해보면 재능의 폭이 넓어져요.","상관":"사회에서는 재치 있고 아이디어가 많은 사람으로 보이기 쉬워요. 옛 책은 상관을 재주가 많고 자존심이 높은 기운이라고 했는데, 그만큼 남다른 감각으로 새로운 방법을 찾아내는 데 강해요. 틀에 박힌 방식을 답답해하고 할 말은 하는 편이라, 능력을 인정받는 동시에 까다롭다는 말을 들을 수도 있어요. 상대의 방식에도 이유가 있다는 걸 먼저 인정해주고 말하면, 날카로운 의견이 훨씬 잘 받아들여져요.","편재":"사회에서는 발이 넓고 기회를 잘 알아보는 사람으로 보이기 쉬워요. 옛 책은 편재를 \"여러 사람의 재물\"이라고 했는데, 그만큼 사람들 사이를 오가며 일과 기회를 연결하는 데 능해요. 움직이는 만큼 성과가 따라오고, 통이 커서 주변에 베푸는 것도 좋아해요. 들어오고 나가는 흐름이 큰 편이니, 내 몫을 따로 챙겨두는 습관을 들이면 넉넉함이 오래 가요.","정재":"사회에서는 꼼꼼하고 성실한 사람으로 보이기 쉬워요. 계획을 세워 차근차근 해내는 데 강하고, 약속한 것은 지키려 해서 믿고 맡길 수 있다는 평을 듣는 편이에요. 옛 책은 재물은 많은 것보다 때에 맞는 것이 중요하다고 했는데, 무리해서 벌이기보다 감당할 만큼을 정확히 해내는 방식이 잘 맞아요. 안정을 중시하다 기회 앞에서 망설일 수 있으니, 작은 범위에서 먼저 시도해보는 연습이 도움이 돼요.","편관":"사회에서는 강단 있고 위기에 강한 사람으로 보이기 쉬워요. 옛 책은 편관을 무조건 흉하게 볼 것이 아니라, 힘을 갖추고 잘 다스리면 크게 이루는 사람이 많다고 했어요. 부담이 큰 자리에서 오히려 집중력이 올라가고, 어려운 일을 맡아 해결하면서 인정받는 편이에요. 스스로에게 엄격해 긴장을 놓지 못하기 쉬우니, 쉬는 시간을 일정처럼 챙겨두면 힘을 오래 쓸 수 있어요.","정관":"사회에서는 책임감 있고 믿음직한 사람으로 보이기 쉬워요. 옛 책은 정관을 귀한 기운이라 하며 흔들리고 부딪히는 것을 꺼린다고 했는데, 그만큼 질서 있고 안정된 환경에서 실력이 잘 드러나요. 정해진 규칙과 약속을 지키는 데서 편안함을 느끼고, 맡은 역할을 끝까지 해내려 해요. 원칙을 지키려다 융통성이 없어 보일 수 있으니, 상황에 따라 한 걸음 양보하는 여유를 곁들이면 신뢰가 더 깊어져요.","편인":"사회에서는 독특한 시선과 깊은 생각을 가진 사람으로 보이기 쉬워요. 남들이 지나치는 부분을 파고드는 힘이 있고, 혼자 몰입할 수 있는 환경에서 실력이 잘 나와요. 옛 책은 편인을 두고 시작은 있으나 끝맺음이 약해지기 쉽다고 했는데, 관심사가 다양해 하나를 마치기 전에 다음 것으로 마음이 옮겨가기 때문이에요. 한 번에 하나씩 작게 끝내는 습관을 들이면, 깊은 생각이 눈에 보이는 결과로 바뀌어요.","정인":"사회에서는 차분하고 배움이 깊은 사람으로 보이기 쉬워요. 옛 책은 정인을 서로 돕고 길러주는 기운이라 하며, 이 기운이 있으면 생각이 깊고 넉넉하다고 했어요. 주변의 도움과 신뢰를 잘 얻는 편이고, 배운 것을 바탕으로 안정적으로 자리를 잡아가요. 받는 데 익숙해져 스스로 나서는 일을 미루기 쉬우니, 배운 것을 직접 써보고 나누는 기회를 만들면 실력이 한층 단단해져요."}$json$::jsonb, 1),
  ('WEALTH_BY_JAESEONG', $json${"none":"원국에 재성(재물을 뜻하는 기운)이 드러나 있지 않아요. 재성이 없다고 재물이 없다는 뜻은 아니고, 돈보다 일의 의미나 사람을 먼저 보는 성향으로 나타나기 쉬워요. 돈 자체를 목표로 삼기보다 실력과 경험을 쌓다 보면 따라오는 흐름에 가까워요. 다만 돈 관리에는 관심이 덜 가기 쉬우니, 들어오고 나가는 돈을 기록하고 저축을 먼저 떼어두는 습관이 특히 도움이 돼요.","some":"원국에 재성이 알맞게 있어 돈을 보는 감각과 현실적인 균형이 있는 편이에요. 옛 책은 재물은 많은 것보다 때에 맞게 있는 것이 좋다고 했는데, 지금 구성이 그 말에 가까워요. 필요한 만큼 벌고 쓸 줄 알아서, 무리한 욕심 없이 생활을 꾸려가는 힘이 있어요. 한 번에 크게 불리려 하기보다 꾸준히 모으는 방식이 가장 잘 맞고, 안정된 기반 위에서 조금씩 넓혀가면 좋아요.","many":"원국에 재성이 여러 개 있어 돈과 기회에 대한 감각이 예민한 편이에요. 눈앞에 기회가 많이 보이고, 여러 일을 동시에 벌이기 쉬운 타입이에요. 옛 책은 재물이 많을수록 그것을 감당할 내 힘이 받쳐줘야 한다고 했는데, 기회가 많아도 체력과 시간이 따라주지 않으면 다 잡기 어렵기 때문이에요. 벌이는 것만큼 정리하고 지키는 계획을 함께 세우고, 감당할 수 있는 만큼만 고르는 습관을 들이면 좋아요."}$json$::jsonb, 1),
  ('LOVE_BY_DAY_GOD', $json${"비견":"배우자 자리(일지)에 비견이 있어요. 친구처럼 대등하고 편한 관계를 원하는 편이라, 서로의 영역을 존중해주는 사람과 잘 맞아요. 함께 있어도 각자의 시간과 취향을 지킬 수 있을 때 마음이 편안해요. 둘 다 자기 주장이 분명해 사소한 일로 팽팽해질 수 있으니, 누가 옳은지보다 어떻게 맞출지를 먼저 이야기하면 관계가 한결 부드러워져요.","겁재":"배우자 자리(일지)에 겁재가 있어요. 함께 도전하고 자극을 주고받는 관계에 끌리는 편이에요. 감정 표현이 솔직하고 뜨거워서 가까워지는 속도가 빠르지만, 그만큼 부딪힐 때도 세게 부딪히기 쉬워요. 다툼이 생기면 이기려 하기보다 한 걸음 물러서는 여유가 관계를 지켜줘요. 돈 문제는 미리 기준을 정해두면 서로 서운할 일이 줄어들어요.","식신":"배우자 자리(일지)에 식신이 있어요. 함께 먹고 쉬고 웃는 편안한 관계를 원하는 편이라, 자극보다 일상의 즐거움을 나눌 수 있는 사람과 잘 맞아요. 상대를 편하게 해주는 넉넉함이 있어 곁에 있으면 마음이 놓인다는 말을 듣기 쉬워요. 편안함에 익숙해져 표현이 줄어들 수 있으니, 가끔은 작은 이벤트나 고마움의 말로 마음을 전해보세요.","상관":"배우자 자리(일지)에 상관이 있어요. 대화가 잘 통하고 재미있는 관계를 중요하게 여기는 편이에요. 감정과 생각을 숨기지 않고 표현해서 관계에 활기가 있지만, 기대가 높아 상대의 부족한 점이 눈에 잘 들어오기도 해요. 솔직한 말이 상처가 되지 않도록 표현을 한 번 다듬고, 고쳐줬으면 하는 점보다 좋은 점을 먼저 말해주면 사이가 훨씬 깊어져요.","편재":"배우자 자리(일지)에 편재가 있어요. 활동적이고 새로운 경험을 함께할 수 있는 관계에 끌리는 편이에요. 상대에게 통 크게 잘해주고 함께 즐기는 시간을 소중히 여겨요. 사람을 좋아하고 바깥 활동이 많아 상대가 서운해할 수 있으니, 둘만의 시간을 따로 정해두면 좋아요. 즐거움이 큰 만큼 서로의 생활 리듬을 맞추는 대화가 도움이 돼요.","정재":"배우자 자리(일지)에 정재가 있어요. 성실하고 믿을 수 있는 안정적인 관계를 원하는 편이에요. 말보다 행동으로 꾸준히 챙기는 타입이라, 시간이 지날수록 신뢰가 쌓이는 관계를 만들어요. 생활을 함께 꾸려가는 계획을 나누며 가까워지기 쉬워요. 마음을 표현하는 데는 서툴 수 있으니, 가끔은 고마움과 애정을 말로도 전해보세요.","편관":"배우자 자리(일지)에 편관이 있어요. 강단 있고 카리스마 있는 사람에게 끌리기 쉬워요. 관계에서도 책임감이 강해 상대를 지키고 이끌려는 마음이 커요. 서로 기준이 높아 긴장감이 생기기 쉬우니, 잘잘못을 따지기보다 솔직하게 마음을 나누는 시간이 큰 힘이 돼요. 편하게 풀어져도 괜찮은 관계라는 믿음이 생기면 사이가 한결 깊어져요.","정관":"배우자 자리(일지)에 정관이 있어요. 예의 바르고 책임감 있는 관계를 원하는 편이에요. 약속을 지키고 서로를 존중하는 모습에서 신뢰가 깊어지고, 오래 함께할 사람을 신중하게 고르는 타입이에요. 격식을 중시하다 보면 속마음을 꺼내는 데 시간이 걸릴 수 있으니, 가까운 사이일수록 편하게 기대는 연습을 해보면 좋아요.","편인":"배우자 자리(일지)에 편인이 있어요. 생각이 통하고 서로의 개성을 이해해주는 관계를 원하는 편이에요. 혼자만의 시간도 존중해주는 사람과 편안하고, 깊은 대화를 나눌 수 있을 때 마음이 열려요. 속마음을 혼자 정리하느라 상대가 답답해할 수 있으니, 정리가 덜 됐더라도 지금 어떤 기분인지 짧게 알려주면 오해가 줄어요.","정인":"배우자 자리(일지)에 정인이 있어요. 서로 챙기고 보살펴주는 안정적인 관계를 원하는 편이에요. 따뜻하게 돌봐주는 사람에게 마음이 가고, 나 역시 상대를 편안하게 품어주려 해요. 받는 배려에 익숙해지지 않도록 고마움을 자주 표현하면 좋아요. 기대고 싶은 마음이 클 때일수록 내가 먼저 해줄 수 있는 것을 찾아보면 관계의 균형이 잘 잡혀요."}$json$::jsonb, 1)
